<script setup>
import {computed,ref,watch} from 'vue';
import {Head,Link,useForm} from '@inertiajs/vue3';
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import AdminWorkspace from '@/Components/AdminWorkspace.vue';
import PageLinks from '@/Components/PageLinks.vue';
import Modal from '@/Components/Modal.vue';
import {requestId} from '@/lib/request-id.mjs';
const props=defineProps({recipients:Object,history:Object,templates:Object,roles:Array,filters:Object});
const search=useForm({q:props.filters.q||'',role:props.filters.role||''});
const form=useForm({recipients:[],template:'support_update',details:'',confirmed:false,request_key:requestId()});
const preview=ref(false),chosen=ref([]);
const labels={user:'User',counselor:'Coach',admin:'Admin',encoder:'Virtual Encoder / Assistant',manager:'Manager',support:'Support'};
const template=computed(()=>props.templates[form.template]);
function select(user,event){if(event.target.checked){if(chosen.value.length>=10){event.target.checked=false;return;}chosen.value.push(user);}else chosen.value=chosen.value.filter(u=>u.id!==user.id);form.recipients=chosen.value.map(u=>u.id);}
watch([()=>form.template,()=>form.details,()=>form.recipients],()=>{form.confirmed=false;form.request_key=requestId();});
const send=()=>form.post(route('staff.emails.send'),{preserveScroll:true,onSuccess:()=>{preview.value=false;chosen.value=[];form.reset();form.request_key=requestId();}});
</script>
<template><Head title="Service emails" /><AuthenticatedLayout><AdminWorkspace section="email">
 <p class="mb-3 text-sm text-muted">Send individual service messages to verified accounts of any role. Maximum 10 recipients per send and 50 emails per staff member in 24 hours. No marketing or password requests.</p>
 <p v-if="$page.props.flash?.success" role="status" class="mb-3 rounded-xl bg-accent-soft p-3 text-sm">{{$page.props.flash.success}}</p>
 <form class="mb-3 flex flex-wrap gap-2" @submit.prevent="search.get(route('staff.emails'),{preserveState:true,preserveScroll:true})"><input v-model="search.q" aria-label="Search recipients" placeholder="Name or email" class="field min-w-0 flex-1" /><select v-model="search.role" aria-label="Recipient role" class="field"><option value="">All roles</option><option v-for="r in roles" :key="r" :value="r">{{labels[r]}}</option></select><button class="action !py-2">Search</button></form>
 <div class="max-h-64 overflow-y-auto rounded-xl border border-border"><label v-for="user in recipients.data" :key="user.id" class="flex items-center gap-3 border-b border-border p-3 text-sm"><input type="checkbox" :checked="form.recipients.includes(user.id)" :disabled="form.processing||(!form.recipients.includes(user.id)&&chosen.length>=10)" @change="select(user,$event)" /><span class="min-w-0 break-words"><strong>{{user.name}}</strong> · {{labels[user.role]}}<span class="block text-xs text-muted">{{user.email}}</span></span></label></div><div class="mt-3 flex justify-between gap-3 text-sm text-accent-text"><Link v-if="recipients.prev_page_url" :href="recipients.prev_page_url" preserve-state preserve-scroll>← Previous</Link><Link v-if="recipients.next_page_url" :href="recipients.next_page_url" preserve-state preserve-scroll>Next →</Link></div>
 <p class="my-3 text-xs text-muted">{{chosen.length}} selected: {{chosen.map(u=>u.name).join(', ')||'None'}}</p>
 <form class="space-y-3 rounded-2xl border border-border bg-surface p-4" @submit.prevent="preview=true"><label class="block text-sm">Template<select v-model="form.template" class="field mt-1 w-full"><option v-for="(t,key) in templates" :key="key" :value="key">{{t.label}}</option></select></label><label class="block text-sm">Case-specific details<textarea v-model="form.details" required minlength="10" maxlength="3000" rows="4" class="field mt-1 w-full" /></label><p v-for="e in form.errors" :key="e" role="alert" class="text-error">{{e}}</p><button class="action !py-2" :disabled="!chosen.length||form.processing">Preview emails</button></form>
 <h3 class="mb-3 mt-5 font-serif text-xl">Sending history</h3><p class="mb-3 text-xs text-muted">Accepted means the mail service accepted the message—not confirmed inbox delivery. Failed sends are not automatically retried.</p><div class="overflow-x-auto rounded-xl border border-border"><table class="w-full text-left text-xs"><thead class="bg-page"><tr><th class="p-3">Recipient</th><th class="p-3">Sent by</th><th class="p-3">Subject</th><th class="p-3">Status</th><th class="p-3">Created (UTC)</th></tr></thead><tbody><tr v-for="e in history.data" :key="e.id" class="border-t border-border"><td class="p-3">{{e.recipient_name}}</td><td class="p-3">{{e.sender_name}}</td><td class="p-3">{{e.subject}}</td><td class="p-3">{{e.status}}</td><td class="p-3">{{e.created_at}}</td></tr></tbody></table></div><PageLinks :data="history" />
 <Modal :show="preview" max-width="lg" @close="preview=false"><form class="space-y-3 p-5" @submit.prevent="send"><h2 class="font-serif text-xl">Confirm individual emails</h2><p class="text-xs text-muted">Each recipient receives a separate message. No other recipient addresses are included.</p><div class="max-h-80 space-y-3 overflow-y-auto"><article v-for="u in chosen" :key="u.id" class="rounded-xl border border-border p-3 text-sm"><strong>To: {{u.name}} · {{u.email}}</strong><p class="mt-2 font-semibold">{{template.subject}}</p><p class="mt-3">Hello {{u.name}},</p><p class="mt-3">{{template.intro}}</p><p class="my-3 whitespace-pre-wrap break-words">{{form.details}}</p><p>For assistance, please use the Support inbox on Intuition Island. Never send your password or payment-card details.</p><p class="mt-3">Intuition Island Support</p></article></div><label class="flex gap-2 text-sm"><input v-model="form.confirmed" type="checkbox" required />I checked every recipient and the message content.</label><p v-for="e in form.errors" :key="e" class="text-error">{{e}}</p><div class="flex justify-end gap-3"><button type="button" @click="preview=false">Cancel</button><button class="action !py-2" :disabled="!form.confirmed||form.processing">Send {{chosen.length}} email{{chosen.length===1?'':'s'}}</button></div></form></Modal>
</AdminWorkspace></AuthenticatedLayout></template>
